"отрезок, соединяющий центр с точкой окружности": "порчае, ки марказро бо нуқтаи давра мепайвандад",
"Урок 30. Окружность и круг: задачи и обобщение": "Дарси 30. Давра ва доира: масъалаҳо ва ҷамъбаст",
