"12 : 4 = 3 без остатка, получается целое число.": "12 : 4 = 3 бе боқимонда, адади бутун мешавад.",
"5 диаметров занимают 60 см: d = 60 : 5 = 12 см.": "5 диаметр 60 см-ро ишғол мекунад: d = 60 : 5 = 12 см.",
"С 40 га собрали 720 ц, сколько с одного гектара?": "Аз 40 га 720 ц ҷамъ карданд, аз як гектар чанд аст?",
"Можно: отмечаем точки из таблицы и соединяем их.": "Мумкин аст: нуқтаҳоро аз ҷадвал қайд мекунем ва онҳоро мепайвандем.",
"Любое число, оканчивающееся на 0, делится на 10.": "Ҳар ададе, ки ба 0 анҷом меёбад, ба 10 қисмат мешавад.",
"Вариантов обеда из 2 первых и 4 вторых блюд — 8.": "Вариантҳои хӯроки нисфирӯзӣ аз 2 хӯроки якум ва 4 хӯроки дуюм — 8.",
"Правильная дробь всегда меньше единицы: 3/6 < 1.": "Каср дуруст ҳамеша аз воҳид хурд аст: 3/6 < 1.",
"радиус: отрезок от центра до точки на окружности": "радиус: порчаи аз марказ то нуқтаи давра",
"Скорость выросла, время то же. Что с расстоянием?": "Суръат зиёд шуд, вақт ҳамон аст. Масофа чӣ мешавад?",
"Расстояние от дома по минутам: 50 м, 150 м, 250 м": "Масофа аз хона аз рӯи дақиқаҳо: 50 м, 150 м, 250 м",
"v сбл. = 70 + 50 = 120 км/ч. t = 240 : 120 = 2 ч.": "v наздик. = 70 + 50 = 120 км/соат. t = 240 : 120 = 2 соат.",
"Длина трассы — 3 000 м. Чему равен 1% этой длины?": "Дарозии роҳ — 3 000 м. 1%-и ин дарозӣ ба чанд баробар аст?",
"Длина трассы — 3 000 м. Чему равен 1% этой длины?": "Дарозии роҳ — 3 000 м. 1%-и ин дарозӣ ба чанд баробар аст?",
"Запиши смешанное число 2 5/6 неправильной дробью.": "Адади омехтаи 2 5/6-ро ҳамчун касри ғайридуруст нависед.",
"Запиши смешанное число 3 2/7 неправильной дробью.": "Адади омехтаи 3 2/7-ро ҳамчун касри ғайридуруст нависед.",
"Урок 12. Сравнение задач вдогонку и с отставанием": "Дарси 12. Муқоисаи масъалаҳои таъқибӣ ва бо ақибмонӣ",
"Нужно собрать 960 ц при 12 ц/га. Сколько гектаров?": "Бояд 960 ц ҷамъ кард ҳангоми 12 ц/га. Чанд гектар?",
"Расстояние от дома по минутам: 100 м, 200 м, 300 м": "Масофа аз хона аз рӯи дақиқаҳо: 100 м, 200 м, 300 м",
"Расстояние от дома по минутам: 500 м, 400 м, 300 м": "Масофа аз хона аз рӯи дақиқаҳо: 500 м, 400 м, 300 м",
"47 − 39 = 18 — Л; 12 · 6 = 72 — И; 24 : 3 = 8 — И.": "47 − 39 = 18 — Н; 12 · 6 = 72 — Д; 24 : 3 = 8 — Д.",
"не высказывание: Сколько будет 6 · 7?; Реши пример": "ҳукм нест: 6 · 7 чанд мешавад?; Мисолро ҳал кун",
"на окружности: радиус 5 см, точка в 5 см от центра": "дар давра: радиус 5 см, нуқта дар масофаи 5 см аз марказ",
