"Знаменатели равны, сравниваем числители: 4 < 9.": "Маҳражҳо баробаранд, суратҳоро муқоиса мекунем: 4 < 9.",
"40 га — это 5/9 участка. Какая площадь участка?": "40 га — ин 5/9-и қитъа. Масоҳати қитъа чӣ қадар аст?",
"Собрали 1 200 ц при 30 ц/га. Какая площадь поля?": "1 200 ц ҷамъ карданд бо 30 ц/га. Масоҳати киштзор чӣ қадар аст?",
"Собрали 1 200 ц при 30 ц/га. Какая площадь поля?": "1 200 ц ҷамъ карданд бо 30 ц/га. Масоҳати киштзор чӣ қадар аст?",
"Поезд прошёл 360 км за 4 ч. Какова его скорость?": "Қатора 360 км-ро дар 4 соат паси сар кард. Суръати он чанд аст?",
"на счёт фигур: сколько треугольников на рисунке?": "ба ҳисоби шаклҳо: дар расм чанд секунҷа ҳаст?",
