"При движении вдогонку скорости вычитают: v₁ − v₂.": "Ҳангоми ҳаракат аз паси ҳам суръатҳо тарҳ карда мешаванд: v₁ − v₂.",
"Над чертой — числитель, под чертой — знаменатель.": "Болои хат — сурат, зери хат — маҳраҷ.",
"60 : 6 = 10 мин — в одной части. 10 · 5 = 50 мин.": "60 : 6 = 10 дақ — дар як қисм. 10 · 5 = 50 дақ.",
"Больше та, у которой числитель больше: 8/9 > 3/9.": "Калонтар он аст, ки сураташ калонтар аст: 8/9 > 3/9.",
"Денег столько же, цена выросла. Что с количеством?": "Пул ҳамон қадар, нарх боло рафт. Миқдор чӣ мешавад?",
"Урожайность 300 ц/га при площади 10 га даст 300 ц.": "Ҳосилнокии 300 ц/га бо масоҳати 10 га 300 ц медиҳад.",
"Расстояние от дома по минутам: 200 м, 400 м, 600 м": "Масофа аз хона аз рӯи дақиқаҳо: 200 м, 400 м, 600 м",
"Расстояние от дома по минутам: 350 м, 250 м, 150 м": "Масофа аз хона аз рӯи дақиқаҳо: 350 м, 250 м, 150 м",
