"9 − 3 = 6, 6 − 1 = 5. Получаем 5/10, это половина.": "9 − 3 = 6, 6 − 1 = 5. 5/10 мешавад, ин нисф аст.",
"S = a · b. Длина 12 м, ширина 5 м: 12 · 5 = 60 м².": "S = a · b. Дарозӣ 12 м, бараъ 5 м: 12 · 5 = 60 м².",
"За 5 минут при скорости 100 м/мин путь равен 500 м.": "Дар 5 дақиқа бо суръати 100 м/дақ роҳ ба 500 м баробар аст.",
"отмечать «да» и «нет» и вычёркивать лишние варианты": "«ҳа» ва «не» қайд кардан ва вариантҳои зиёдатиро хат задан",
"Посмотри, что стало с числителем и со знаменателем.": "Нигоҳ кун, ки бо сурат ва бо маҳраҷ чӣ шуд.",
"Всего 21 мяч. 2/3 мячей — красные. Сколько красных?": "Ҳамагӣ 21 тӯб. 2/3-и тӯбҳо сурх аст. Чандто сурх аст?",
"Урожайность 45 ц/га, площадь 20 га. Сколько собрали?": "Ҳосилнокӣ 45 ц/га, масоҳат 20 га. Чӣ қадар ҷамъ карданд?",
"Одна из этих записей — истинное высказывание. Какая?": "Яке аз ин навиштаҳо — ҳукми дуруст аст. Кадомаш?",
"Четырёхзначные числа из цифр 5, 6, 7, 8 без повторов": "Ададҳои чаррақама аз рақамҳои 5, 6, 7, 8 бе такрор",
